//! Golden parity: legacy settings coercion vs Python `app_settings._coerce`
//! (fixtures/parity/settings_coerce.json, generated by tools/parity/generate.py).

use serde_json::{Value, json};
use sleuth_core::settings::{Settings, legacy_float};

fn fixture(name: &str) -> Value {
    let path = format!("{}/../../fixtures/parity/{name}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(&path).expect(&path)).unwrap()
}

#[test]
fn coercion_matches_python() {
    let defaults = Settings::default().to_map();
    let cases = fixture("settings_coerce.json")["cases"].as_array().unwrap().clone();
    assert!(!cases.is_empty());
    for case in cases {
        let key = case["key"].as_str().unwrap();
        let input = &case["input"];
        let expected = &case["output"];
        let got: Value = match &defaults[key] {
            Value::Bool(d) => json!(input.as_bool().unwrap_or(*d)),
            Value::Number(d) => json!(legacy_float(input).unwrap_or(d.as_f64().unwrap())),
            other => panic!("unexpected default type for {key}: {other}"),
        };
        assert_eq!(&got, expected, "key={key} input={input}");
    }
}

#[test]
fn legacy_import_sanitizes_values_python_would_accept() {
    // Python coerces False -> 0.0 for map_square_in, which later divides by zero.
    let s = Settings::from_legacy_json(&json!({"map_square_in": false, "map_margin_in": -1}));
    assert_eq!(s.map_square_in, 1.0);
    assert_eq!(s.map_margin_in, 0.0);
}
